SPECS += [
 dict(ref='17.8',method='CircusTower',params=[('people','aai')],result='ai',mutation='none',
 description='Arrange the largest possible number of people into a tower so each person above another is strictly shorter AND strictly lighter. Each input row is [height,weight]. Return original zero-based row indices in top-to-bottom order, so both height and weight strictly increase along the returned sequence. Any maximum-length tower is accepted.',
 constraints=['people is a nonnull array of 0..200 nonnull two-integer rows. Heights and weights are in 1..1000000. Equal heights, equal weights and identical rows for different people are allowed, but equality in either dimension prevents stacking that pair.', 'Use each original person at most once and preserve the input outer/row objects, values and order. Return original row indices, not indices in a privately sorted copy. Empty input returns [].'],
 why='Sort original indices by height, then use dynamic programming over possible final people. A shorter/lighter predecessor can extend a valid tower; retaining a predecessor index reconstructs an actual maximum tower rather than only its length. Checking BOTH strict comparisons keeps equal dimensions from forming invalid links.',
 correctness='Every predecessor of a person in a valid top-to-bottom tower has smaller height and therefore occurs earlier in the private sorted order. For each person, the recurrence takes one plus the largest valid predecessor tower length, or one if none exists. Induction over that order proves each recorded length is optimal among towers ending there. The global best endpoint consequently has maximum possible length. Following its recorded predecessor links reconstructs only strict height/weight links, and reversing them yields top-to-bottom original indices. Private index sorting leaves caller rows unchanged.',
 walkthrough='For people=[[65,100],[70,150],[56,90]], the sorted index order is [2,0,1]. Each person can follow the previous one, so return [2,0,1]. For [[60,100],[60,90]], only one person can be used despite the different weights, because heights must also increase strictly.',example=([[[65,100],[70,150],[56,90]]],[2,0,1]),
 time='O(n^2) dynamic-programming comparisons after O(n log(n+1)) private index sorting.',space='O(n) index, length, predecessor and returned-index storage.',edges=['Empty/single person, duplicate rows and ties in either dimension.','A best tower using neither original input order nor every person; arbitrary maximum-tower ties.'],related='Original row IDs replace the public HtWt wrapper references without losing person identity; the grader accepts every maximum tower, not one incidental tie choice.'),
 dict(ref='17.13',method='ReSpace',params=[('text','s'),('dictionary','as')],result='strings',mutation='none',
 description='Split a spaceless text into nonempty tokens so the total number of characters in unrecognized tokens is as small as possible. A token is recognized exactly when it appears in dictionary. Return the actual token sequence, whose concatenation must equal text. Any minimum-cost tokenization is accepted; no characters may be deleted, changed or reordered.',
 constraints=['text is a nonnull string of 0..200 lowercase ASCII letters. dictionary is a nonnull array of 0..200 nonempty lowercase ASCII words of length at most 20. Duplicate entries are vocabulary duplicates, not consumable supplies. A known word may be used repeatedly.', 'An unrecognized token costs its full character length. Unknown text may be grouped or split into individual-character tokens at the same cost. Empty text returns []; empty tokens are invalid. Preserve dictionary order/entries and text.'],
 why='A prefix either ends with one unrecognized character, costing one extra, or with a recognized dictionary word, costing nothing beyond the best preceding prefix. Considering every dictionary-length suffix handles overlapping word choices that greedy splitting can miss. Save the chosen preceding position to reconstruct tokens as well as the minimum cost.',
 correctness='Every produced tokenization ends in either a recognized word or an unrecognized segment. The latter can be split into single unknown characters without changing its cost, so the recurrence considering one unknown character is sufficient. Removing the final recognized word or unknown character leaves a strictly shorter prefix with optimal cost by induction. Taking the minimum over these possibilities therefore gives the global minimum. Saved predecessor positions strictly decrease during reconstruction and concatenate to the complete original text, proving both valid coverage and minimum cost.',
 walkthrough='For text=abcd and dictionary=[ab,abc,cd], choosing the longest first word abc leaves unknown d with cost 1. Prefix DP instead finds ab+cd with cost 0 and returns [ab,cd]. For text=xyz with no dictionary, [x,y,z] and [xyz] both have minimum cost 3 and are accepted.',example=(['abcd',['ab','abc','cd']],['ab','cd']),
 time='Expected O(D+N*L^2) character work for D dictionary characters, text length N and maximum dictionary word length L: at most L suffix checks per prefix, each copying/hashing up to L characters. Hash collisions can worsen lookup.',space='O(D+N) dictionary and DP/predecessor/output storage, plus O(L) temporary substring characters.',edges=['Empty text or dictionary, all-known and all-unknown text.','Overlapping words where greedy longest-prefix choice fails; repeated vocabulary use and multiple optimal tokenizations.'],related='The public ReSpace task returns an actual parsing, not only its invalid-character count. Returned tokens make that reconstruction executable and allow every optimum tie.'),
 dict(ref='17.22',method='WordTransformation',params=[('start','s'),('stop','s'),('dictionary','as')],result='strings',mutation='none',
 description='Find a path of dictionary words from start to stop, changing exactly one letter at each step. Return both endpoints and every intermediate word, with no repeated word. Any valid such path is accepted; return [] when no transformation exists. If start==stop, return [start].',
 constraints=['start and stop are nonempty lowercase ASCII words of the same length 1..8. dictionary contains 1..1000 nonempty lowercase ASCII words of length at most 8 and includes both endpoints. Duplicates are allowed and do not create new vertices; words of other lengths cannot participate.', 'Every returned word must be in dictionary, and each adjacent pair must differ in exactly one position. No letter insertion, deletion, transposition or arbitrary replacement of several letters is allowed. Preserve all inputs. The reference finds a shortest path, but shortest length is not a grading requirement.'],
 why='Treat words as graph vertices and one-letter changes as edges. Breadth-first search discovers each word once and stores the predecessor that first reached it. Generate possible neighbors by changing one position to each other letter and checking dictionary membership, avoiding a comparison against every word for every step.',
 correctness='Every generated neighbor changes exactly one position and is queued only if it is a dictionary word, so every predecessor edge is a legal transformation. Visited tracking prevents repeated vertices and guarantees finite exploration. Induction on path length shows BFS discovers every reachable word; thus queue exhaustion proves no path exists. When stop is found, following predecessors back to start and reversing yields a valid path with both endpoints and no repeated word. The identical-endpoint case is the one-word path.',
 walkthrough='With dictionary=[cat,cot,cog,dog], start cat changes a to o to reach cot, then t to g to reach cog, then c to d to reach dog. Return [cat,cot,cog,dog]. cat->dog directly is invalid because several positions differ.',example=(['cat','dog',['cat','cot','cog','dog']],['cat','cot','cog','dog']),
 time='Expected O(D+26*W*L^2) character work for D dictionary characters, W reachable length-L words and copying/hashing each generated length-L candidate. At most 26*L candidates are tried per expanded word.',space='O(D+W*L) dictionary, visited/predecessor/queue and returned-word storage.',edges=['Equal endpoints, disconnected components and direct one-letter neighbors.','Repeated dictionary entries, other word lengths, cycles and several valid paths.'],related='The public variants differ on endpoints missing from the dictionary; this bank removes that uncertainty with an explicit endpoint-membership precondition and accepts every valid path.'),
 dict(ref='17.25',method='LargestWordRectangle',params=[('words','as')],result='strings',mutation='none',
 description='Return a rectangle of letters with the largest possible area such that every row, read left to right, and every column, read top to bottom, is a dictionary word. Return the rows as equal-length strings. Any maximum-area rectangle is accepted; return [] if no nonempty rectangle exists.',
 constraints=['words is a nonnull array of 0..20 nonempty lowercase ASCII words, each 1..5 letters. Duplicate entries describe the same vocabulary word. The same word may be reused as multiple rows or columns; dictionary occurrences are not consumed.', 'A rectangle has positive height and width. Row words have length equal to width and column words length equal to height, so both dimensions are at most the largest dictionary word length. A square is not required. Preserve the input and all entries.'],
 why='Try height/width pairs from largest area downward. For a fixed pair, append candidate row words and check whether every partial column is still a prefix of some dictionary word of the required column height. An impossible prefix can never be repaired by later rows, so pruning avoids exploring the rest of that branch.',
 correctness='Every completed accepted row sequence uses dictionary row words and has each full column in the required-height dictionary group, so it is a valid rectangle. At a partial state, a column prefix absent from every possible full column word cannot extend to any valid solution; rejecting it is safe. Trying every candidate row at each unpruned depth therefore finds a rectangle for those dimensions whenever one exists. Dimensions are considered in decreasing area, so the first successful rectangle has globally maximum area. Exhaustion proves no nonempty rectangle exists.',
 walkthrough='For words=[ab,ba], rows [ab,ba] make columns ab and ba, giving area 4. Rows [ba,ab] are another accepted maximum. With words=[aa], reusing aa twice gives [aa,aa], whose columns are also aa. With only [ab], no compatible column words exist, so return [].',example=([['ab','ba']],['ab','ba']),
 time='Exponential search in the maximum word length L: O(D^L*(L+1)^4) conservative character work for at most D distinct dictionary words across O(L^2) dimension pairs, including copying/hashing column prefixes. L<=5 bounds this search; pruning can greatly reduce it.',space='O(D*(L+1)^2) dictionary/prefix characters plus O(L^2) candidate/result grid and O(L) recursion frames.',edges=['Empty vocabulary, no compatible rectangle, one-letter words and nonsquare maxima.','Reused words, duplicate entries, equal-area alternate rectangles and column-prefix dead ends.'],related='The public rectangle search permits repeated row choices and maximizes area. Returned rows replace its Rectangle wrapper while preserving both row/column word requirements.'),
 dict(ref='17.26',method='SparseSimilarities',params=[('documentIds','ai'),('documents','aai')],result='aai',mutation='none',
 description='Compute positive Jaccard similarities between distinct documents treated as sets of integer word IDs. Return one row [smallerDocumentId,largerDocumentId,intersectionSize,unionSize] for each pair with a nonempty intersection. The exact similarity is intersectionSize/unionSize; no floating-point rounding is involved. Sort result rows by the two document IDs.',
 constraints=['documentIds has 0..200 distinct signed 32-bit IDs. documents has the same length; each nonnull row contains 0..200 distinct signed 32-bit word IDs. Document/word IDs are identities, not array positions or counts. Preserve both input arrays, every document row and all order/values.', 'Each returned pair appears once, with IDs in increasing order. Omit disjoint pairs, including pairs of empty documents. Counts are the actual intersection/union sizes, not reduced fraction components. Empty documents have no positive-similarity partner.'],
 why='Most document pairs may share nothing. Build an inverted index from each word ID to the document positions containing it. A pair appears together once for each shared word, so incrementing only those pairs computes positive intersection sizes without testing every disjoint pair. Document lengths then give union=lengthA+lengthB-intersection.',
 correctness='Because each document contains a word ID at most once, a word posting list contributes exactly one increment to each pair sharing that word. Summing over words therefore yields the exact intersection count for every recorded pair, and records no zero-intersection pair. Inclusion-exclusion gives its exact union size. Mapping positions back to the supplied unique document IDs, normalizing pair orientation and sorting yields each required row once. Empty documents appear in no posting list and correctly contribute no positive pair.',
 walkthrough='For IDs [10,20,30] and documents [[1,2],[2,3],[]], word 2 links documents 10 and 20 once. Their intersection is 1 and union is 2+2-1=3, so return [[10,20,1,3]], representing exact similarity 1/3. Empty document 30 creates no positive pair.',example=([[10,20,30],[[1,2],[2,3],[]]],[[10,20,1,3]]),
 time='Expected O(T+sum(f_w^2)+P log(P+1)) time for T word occurrences, posting frequency f_w per word and P positive document pairs. Posting-pair work can still be quadratic when many documents share words.',space='O(T+P+n) inverted postings, sparse intersection counters and result rows for n documents; no dense n-by-n matrix is allocated.',edges=['No documents, empty/disjoint documents and identical sets.','Arbitrary/signed-endpoint document IDs, input order differing from ID order and several shared words.','Word duplicates inside one document are outside the set-input domain.'],related='Exact intersection/union counts represent the public task\'s Jaccard value without decimal tolerance ambiguity. Original document IDs are retained rather than silently replacing them with positions.'),
]
